test("A search finds no draft: a word only a draft holds matches nothing", async ({ browser, baseURL, page, context }) => {
  const j = await Journey.start({ browser, baseURL, page, context }, [], { logs: false });
  try {
    await j.goto("/search?q=workbench");
    await j.expectText(null, j.text("Nothing mentions “workbench”."), undefined);
    await j.expectNoText(null, j.text("Notes Toward a Workbench"), undefined);
    await expect(j.page.getByRole("article")).toHaveCount(0);
  } finally {
    await j.close();
  }
});
